"""Load and validate project YAML files (DEP-05).

Every error raises :class:`ConfigError` with a message of the form
``<file>: <field>: <problem>`` so that startup can fail fast and clearly.
"""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any

import yaml
from pydantic import ValidationError

from heliopuddle.config.models import ProjectConfig

#: File name of the generated default config, inside the data dir.
DEFAULT_CONFIG_NAME = "default_config.yaml"

_DEFAULT_CONFIG_TEMPLATE = r"""
# Generated by heliopuddle because no project files were found in the config
# directory (HELIOPUDDLE_CONFIG_DIR). Edit this file to change the default
# setup, or put your own project YAML files in that directory, which then
# replace this one. Never overwritten once it exists.
project: default
storage_locations:
  - name: primary
    url: @PRIMARY@

  - name: archive
    url: @ARCHIVE@

# first matching rule wins (see docs/design/versioning.md)
versioning:
  # Number versions: file_v8.csv, file_V09.csv, file_v10.csv are versions 8, 9, 10
  - paths: ["**"]
    version_type: number
    extraction_pattern: '_[vV](?P<version>\d{1,5})\.[^./]+$'
  # Text versions, e.g. major.minor (file_v2.12.csv -> "002.0012"):
  # - paths: ["**"]
  #   version_type: text
  #   extraction_pattern: '_v(?P<major>\d{1,3})\.(?P<minor>\d{1,4})\.(?P<ext>[^./]+)$'
  #   version_text: '{major:0>3}.{minor:0>4}'

rules:
  - name: auto-archive-old-versions-hourly
    action: move
    source: primary
    destination: archive
    match:
      paths: ["**"]
      is_latest: false
      age:
        modified: { older_than: 1h }
    options:
      overwrite: false
      check_for_space: true
      batch: { max_files: 10 }
    schedule: "0 * * * *"
"""

# ${VAR} or ${VAR:-default}
_ENV_REF = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)(?::-([^}]*))?\}")


class ConfigError(Exception):
    """Invalid configuration. The message names the file and the field."""


class _UnsetVariable(Exception):
    def __init__(self, field: str, name: str) -> None:
        super().__init__(f"{field}: environment variable {name} is not set and has no default")


def _expand(value: str, field: str) -> str:
    def repl(match: re.Match[str]) -> str:
        name, default = match.group(1), match.group(2)
        env = os.environ.get(name)
        if env is not None:
            return env
        if default is not None:
            return default
        raise _UnsetVariable(field, name)

    return _ENV_REF.sub(repl, value)


def _expand_tree(value: Any, field: str) -> Any:
    if isinstance(value, str):
        return _expand(value, field)
    if isinstance(value, dict):
        return {k: _expand_tree(v, f"{field}.{k}") for k, v in value.items()}
    if isinstance(value, list):
        return [_expand_tree(v, f"{field}.{i}") for i, v in enumerate(value)]
    return value


def _expand_storage_locations(data: dict[str, Any]) -> None:
    locations = data.get("storage_locations")
    if not isinstance(locations, list):
        return  # schema validation reports it
    for i, loc in enumerate(locations):
        if not isinstance(loc, dict):
            continue
        field = f"storage_locations.{i}"
        if isinstance(loc.get("url"), str):
            loc["url"] = _expand(loc["url"], f"{field}.url")
        if "storage_options" in loc:
            loc["storage_options"] = _expand_tree(
                loc["storage_options"], f"{field}.storage_options"
            )


def _rule_name(data: dict[str, Any], loc: tuple[int | str, ...]) -> str | None:
    """The name of the rule an error location points into, if it has one."""
    if len(loc) < 2 or loc[0] != "rules" or not isinstance(loc[1], int):
        return None
    rules = data.get("rules")
    if not isinstance(rules, list) or not 0 <= loc[1] < len(rules):
        return None
    rule = rules[loc[1]]
    name = rule.get("name") if isinstance(rule, dict) else None
    return name if isinstance(name, str) else None


def _format_validation_error(path: Path, error: ValidationError, data: dict[str, Any]) -> str:
    lines = []
    for err in error.errors():
        loc = ".".join(str(p) for p in err["loc"]) or "(root)"
        name = _rule_name(data, err["loc"])
        where = f"rule {name!r}: {loc}" if name else loc
        lines.append(f"{path}: {where}: {err['msg']}")
    return "\n".join(lines)


def load_project(path: Path) -> ProjectConfig:
    """Load one project file, resolving ``${VAR}`` references.

    ``${VAR}`` and ``${VAR:-default}`` are expanded in each storage location's
    ``url`` and in every string value (recursively) of its ``storage_options``.
    ``{{ prefect.blocks.secret.<name> }}`` placeholders there are only checked
    for syntax; they are resolved when the storage location is used (STO-18).

    Args:
        path: the YAML file.

    Returns:
        The validated project config.

    Raises:
        ConfigError: on an unreadable file, invalid YAML, schema errors or an
            unset environment variable or a malformed placeholder. The message
            names the file, the field and, for a rule, the rule's name.
    """
    path = Path(path)
    try:
        text = path.read_text()
    except OSError as e:
        raise ConfigError(f"{path}: cannot read file: {e.strerror or e}") from None
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as e:
        raise ConfigError(f"{path}: invalid YAML: {e}") from None
    if not isinstance(data, dict):
        raise ConfigError(f"{path}: (root): expected a mapping, got {type(data).__name__}")
    try:
        _expand_storage_locations(data)
    except _UnsetVariable as e:
        raise ConfigError(f"{path}: {e}") from None
    try:
        project = ProjectConfig.model_validate(data)
    except ValidationError as e:
        raise ConfigError(_format_validation_error(path, e, data)) from None
    for index, location in enumerate(project.storage_locations):
        location.set_origin(f"{path}: storage_locations.{index}")
    return project


def project_files(config_dir: Path) -> list[Path]:
    """Return the ``*.yaml``/``*.yml`` files in ``config_dir`` in name order.

    Args:
        config_dir: directory holding one YAML file per project.

    Returns:
        The project files; empty if the directory is missing or has none.
    """
    config_dir = Path(config_dir)
    if not config_dir.is_dir():
        return []
    return sorted(p for p in config_dir.iterdir() if p.is_file() and p.suffix in {".yaml", ".yml"})


def has_project_files(config_dir: Path) -> bool:
    """Return True if ``config_dir`` holds at least one project file."""
    return bool(project_files(config_dir))


def default_config_path(data_dir: Path) -> Path:
    """Where the default project's config file lives: ``<data_dir>/default_config.yaml``."""
    return Path(data_dir) / DEFAULT_CONFIG_NAME


def write_default_config(data_dir: Path) -> Path:
    """Write the default project's config file, unless it already exists (DEP-10).

    The file defines project ``default`` with storage locations ``primary`` and
    ``archive`` at ``<data_dir>/primary-storage`` and ``<data_dir>/archive-storage``
    (absolute; created at startup), two version rules, and an hourly rule moving
    non-latest files modified over an hour ago from primary to archive. An existing
    file is never overwritten, so edits to it persist.

    Args:
        data_dir: the data directory (``HELIOPUDDLE_DATA_DIR``).

    Returns:
        The path of the config file.

    Raises:
        ConfigError: if the file cannot be written.
    """
    path = default_config_path(data_dir)
    if path.exists():
        return path
    root = Path(data_dir).resolve()
    text = (
        _DEFAULT_CONFIG_TEMPLATE.lstrip("\n")
        .replace("@PRIMARY@", (root / "primary-storage").as_uri())
        .replace("@ARCHIVE@", (root / "archive-storage").as_uri())
    )
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
    except OSError as e:
        raise ConfigError(f"{path}: cannot write default config: {e.strerror or e}") from None
    return path


def load_projects(
    config_dir: Path, *, default_data_dir: Path | None = None
) -> dict[str, ProjectConfig]:
    """Load every ``*.yaml``/``*.yml`` file in ``config_dir``, keyed by project name.

    Files are read in name order, so the result is ordered by file name.

    Args:
        config_dir: directory holding one YAML file per project.
        default_data_dir: if given and ``config_dir`` is missing or holds no
            project files, write (if missing) and load the default config file
            :func:`default_config_path` under this data directory instead of
            failing.

    Returns:
        Project configs keyed by project name.

    Raises:
        ConfigError: on any invalid file (including the default config file) or
            duplicate project names; without
            ``default_data_dir`` also on a missing directory or no project files.
    """
    config_dir = Path(config_dir)
    files = project_files(config_dir)
    if not files:
        if default_data_dir is not None:
            project = load_project(write_default_config(default_data_dir))
            return {project.project: project}
        if not config_dir.is_dir():
            raise ConfigError(f"{config_dir}: not a directory (set HELIOPUDDLE_CONFIG_DIR)")
        raise ConfigError(f"{config_dir}: no project files (*.yaml, *.yml)")
    projects: dict[str, ProjectConfig] = {}
    sources: dict[str, Path] = {}
    for path in files:
        project = load_project(path)
        if project.project in projects:
            raise ConfigError(
                f"{path}: project: duplicate project name {project.project!r} "
                f"(also in {sources[project.project]})"
            )
        projects[project.project] = project
        sources[project.project] = path
    return projects
